// ── wbs_tasks ─────────────────────────────────────────────────────────────────

// @table wbs_tasks
export function countWbsTasksByDepartmentIdsWithCrossDeptStatusRequested(departmentIds: readonly (string | number)[]) {
  return db()
    .from("wbs_tasks")
    .select("id", { count: "exact", head: true })
    .in("department_id", departmentIds)
    .eq("cross_dept_status", "requested");
}

// @table wbs_tasks
export function listWbsTasks() {
  return db().from("wbs_tasks").select("status");
}

// @table wbs_tasks
export function listWbsTasksByProjectId(projectId: string | number | boolean) {
  return db()
    .from("wbs_tasks")
    .select("id, task_code, task_name, status, progress, priority, discipline, start_date, end_date, delay_status, owner_name")
    .eq("project_id", projectId)
    .order("end_date", { ascending: true, nullsFirst: false });
}
